    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">D = -y + √3 + y + y + <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> + √3 - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">5</span></span> - y + y - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> - √3</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">D = (-y + y + y - y + y) + (<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">5</span></span> - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span>) + (√3 + √3 - √3)</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">D = y - <span class=\"frac\"><span class=\"num\">6</span><span class=\"den\">5</span></span> + √3</span>"}],
