    correction: [{"quoi":"نترجم المعطى","math":"متساويان معناه <span dir=\"ltr\" class=\"expr\">D = 1 - π</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">y - <span class=\"frac\"><span class=\"num\">6</span><span class=\"den\">5</span></span> + √3 = 1 - π</span>"},{"quoi":"نعزل y","math":"<span dir=\"ltr\" class=\"expr\">y = 1 - π - (-<span class=\"frac\"><span class=\"num\">6</span><span class=\"den\">5</span></span> + √3)</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\">1 - π - (-<span class=\"frac\"><span class=\"num\">6</span><span class=\"den\">5</span></span> + √3) = <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">5</span></span> - √3 - π</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">y = <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">5</span></span> - √3 - π</span>"}],
