    correction: [{"quoi":"نترجم المعطى","math":"متساويان معناه <span dir=\"ltr\" class=\"expr\">E = -b - 3 - π</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">a - b + 3 - π = -b - 3 - π</span>"},{"quoi":"نعزل a","math":"<span dir=\"ltr\" class=\"expr\">a = -b - 3 - π - (-b + 3 - π)</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\">-b - 3 - π - (-b + 3 - π) = -6</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">a = -6</span>"}],
