    correction: [{"quoi":"نحدّد إشارة ما بداخل القيمة المطلقة","math":"<span dir=\"ltr\" class=\"expr\">-<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> + √3</span> عدد موجب تقريبا يساوي 1.40"},{"quoi":"نزيل القيمة المطلقة","math":"<span dir=\"ltr\" class=\"expr\">|-<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> + √3| = -<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> + √3</span>"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">E = -<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> + √3 - 1 - 5 - <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">5</span></span> + √3 + √3 - √3 - 3 - x - y + <span class=\"frac\"><span class=\"num\">34</span><span class=\"den\">5</span></span></span>"},{"quoi":"نجمع الحدود المتشابهة","math":"نجمع الأعداد الناطقة معا و الأعداد الصمّاء معا"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">E = -x - y - <span class=\"frac\"><span class=\"num\">13</span><span class=\"den\">3</span></span> + 2√3</span>"}],
