    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">F = -<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> + b + <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">2</span></span> + π + a - a - π + a - 2b + π</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">F = (a - a + a) + (b - 2b) + (-<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> + <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">2</span></span>) + (π - π + π)</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">F = a - b + 3 + π</span>"}],
