    correction: [{"quoi":"نختصر الطرف الأوّل","math":"<span dir=\"ltr\" class=\"expr\">-<span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span> - [5 + (-3 + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> - y)] + (-9 + π) + 11 - 2π = y - 3 - π</span>"},{"quoi":"نكتب المعادلة المختصرة","math":"<span dir=\"ltr\" class=\"expr\">y - 3 - π = -<span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> + π</span>"},{"quoi":"نعزل y","math":"<span dir=\"ltr\" class=\"expr\">y = -<span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> + π - (-3 - π)</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\">-<span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> + π - (-3 - π) = <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">3</span></span> + 2π</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">y = <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">3</span></span> + 2π</span>"}],
