    correction: [{"quoi":"نختصر الطرف الأوّل","math":"<span dir=\"ltr\" class=\"expr\">-6 - [<span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">3</span></span> - (-x - 1)] + <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">5</span></span> + 3 + <span class=\"frac\"><span class=\"num\">29</span><span class=\"den\">15</span></span> - √3 = -x - 4 - √3</span>"},{"quoi":"نكتب المعادلة المختصرة","math":"<span dir=\"ltr\" class=\"expr\">-x - 4 - √3 = -4</span>"},{"quoi":"نعزل x","math":"<span dir=\"ltr\" class=\"expr\">-x = -4 - (-4 - √3)</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\">-4 - (-4 - √3) = √3</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = -√3</span>"}],
