    correction: [{"quoi":"نختصر الطرف الأوّل","math":"<span dir=\"ltr\" class=\"expr\">(-√2 - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span>) + [√2 + (-b - √2)] + [-<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> + <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span>] + [-<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">4</span></span>] + 2b + <span class=\"frac\"><span class=\"num\">337</span><span class=\"den\">60</span></span> = b + <span class=\"frac\"><span class=\"num\">6</span><span class=\"den\">5</span></span> - √2</span>"},{"quoi":"نكتب المعادلة المختصرة","math":"<span dir=\"ltr\" class=\"expr\">b + <span class=\"frac\"><span class=\"num\">6</span><span class=\"den\">5</span></span> - √2 = <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">3</span></span></span>"},{"quoi":"نعزل b","math":"<span dir=\"ltr\" class=\"expr\">b = <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">3</span></span> - (<span class=\"frac\"><span class=\"num\">6</span><span class=\"den\">5</span></span> - √2)</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">3</span></span> - (<span class=\"frac\"><span class=\"num\">6</span><span class=\"den\">5</span></span> - √2) = <span class=\"frac\"><span class=\"num\">17</span><span class=\"den\">15</span></span> + √2</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">b = <span class=\"frac\"><span class=\"num\">17</span><span class=\"den\">15</span></span> + √2</span>"}],
