    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">M = <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">6</span></span> + a - <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> - a + √2 - b - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">4</span></span> + <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span> + a + 3b - <span class=\"frac\"><span class=\"num\">25</span><span class=\"den\">12</span></span></span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">M = (a - a + a) + (-b + 3b) + (<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">6</span></span> - <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">4</span></span> + <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span> - <span class=\"frac\"><span class=\"num\">25</span><span class=\"den\">12</span></span>) + √2</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = a + 2b - 1 + √2</span>"}],
