    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">N = b + 4 + <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">3</span></span> - a - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">4</span></span> - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">4</span></span> + 3a - <span class=\"frac\"><span class=\"num\">19</span><span class=\"den\">3</span></span> + π</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">N = (-a + 3a) + b + (4 + <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">3</span></span> - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">4</span></span> - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">4</span></span> - <span class=\"frac\"><span class=\"num\">19</span><span class=\"den\">3</span></span>) + π</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">N = 2a + b - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> + π</span>"}],
