    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">N = 1 + π + π - <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> - b + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">5</span></span> + b + a + π + 3b - <span class=\"frac\"><span class=\"num\">87</span><span class=\"den\">10</span></span> - 4π</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">N = a + (-b + b + 3b) + (1 - <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">5</span></span> - <span class=\"frac\"><span class=\"num\">87</span><span class=\"den\">10</span></span>) + (π + π + π - 4π)</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">N = a + 3b - 9 - π</span>"}],
