    correction: [{"quoi":"نترجم المعطى","math":"عددان متقابلان مجموعهما منعدم<span dir=\"ltr\" class=\"expr\">: M + N = 0</span>"},{"quoi":"نجمع الشكلين المختصرين","math":"<span dir=\"ltr\" class=\"expr\">M + N = 4a + 4b - 11 - √2 - π</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">4a + 4b - 11 - √2 - π = 0</span>"},{"quoi":"نعزل حدود الحرفين","math":"<span dir=\"ltr\" class=\"expr\">4a + 4b = 11 + √2 + π</span>"},{"quoi":"نقسم على المعامل","math":"<span dir=\"ltr\" class=\"expr\">a + b = <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">4</span></span> + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">4</span></span> √2 + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">4</span></span> π</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">a + b = <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">4</span></span> + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">4</span></span> √2 + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">4</span></span> π</span>"}],
